# Snippet 1: The Parent Class
class Enemy:
    def __init__(self, name, hp):
        self.name = name
        self.hp = hp

    def attack(self):
        return 'Basic punch!'

# Snippet 2: The Child Class inheriting from Enemy
class Dragon(Enemy):
    def __init__(self, name, hp, fire_damage):
        # Call the parent constructor
        super().__init__(name, hp)
        self.fire_damage = fire_damage

    # Snippet 3: Overriding a parent method
    def attack(self):
        return f'Breathes fire for {self.fire_damage} damage!'

boss = Dragon('Smaug', 1000, 150)
print(boss.name, 'attacks:', boss.attack())

