# Snippet 2: Implementing Dunder Methods
class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return f'Vector({self.x}, {self.y})'

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

# Snippet 3: Using the magic
v1 = Vector(2, 4)
v2 = Vector(3, 1)
v3 = v1 + v2 # Triggers __add__
print(v3)    # Triggers __str__, prints 'Vector(5, 5)'

# Snippet 1: Catching a crash
user_input = '0'
try:
    # Trying to divide by zero
    result = 100 / int(user_input)
    print('Result:', result)
except ZeroDivisionError:
    print('Error: You cannot divide by zero!')
except ValueError:
    print('Error: Please enter a valid number!')

