# Snippet 1: Raising built-in exceptions
def register_user(age):
    if type(age) is not int:
        raise TypeError('Age must be an integer')
    if age < 13:
        # Deliberately halt execution
        raise ValueError('User must be at least 13 years old')
    print('User registered successfully!')

# Snippet 2: Catching the raised exception
try:
    register_user(10)
except ValueError as e:
    print('Registration Failed:', e)

# Snippet 3: Custom Exceptions
class InsufficientFundsError(Exception):
    pass

def withdraw(balance, amount):
    if amount > balance:
        raise InsufficientFundsError('Not enough money!')
    return balance - amount

import random

def roll_stat():
    # Roll a 6-sided die 3 times and sum it (3-18 range)
    return sum(random.randint(1, 6) for _ in range(3))

def generate_character(name):
    classes = ['Warrior', 'Mage', 'Rogue', 'Cleric']
    char_class = random.choice(classes)

    # Use a dictionary to bundle the character data
    character = {
        'name': name,
        'class': char_class,
        'level': 1,
        'stats': {
            'STR': roll_stat(),
            'DEX': roll_stat(),
            'INT': roll_stat()
        }
    }

    # Class-specific bonuses
    if char_class == 'Warrior':
        character['stats']['STR'] += 2
    elif char_class == 'Mage':
        character['stats']['INT'] += 2

    return character

# Generate and display the character
hero = generate_character('Arthas')
print('--- New Character Generated ---')
for key, val in hero.items():
    if key == 'stats':
        print('Stats:')
        for stat_key, stat_val in val.items():
            print(f'  {stat_key}: {stat_val}')
    else:
        print(f'{key.capitalize()}: {val}')
